{"cmd":"python - <<'PY'
import pandas as pd
import numpy as np

df=pd.read_csv('benchmark/data.csv')
df['date']=pd.to_datetime(df['date'])
map_level={'Low':'Low','High':'High','Medium':'High','Very High':'High'}
df['subsidy_bin']=df['subsidy_level'].map(map_level)
g=df.groupby(['date','subsidy_bin']).agg(petrol=('petrol_usd_liter','mean'),diesel=('diesel_usd_liter','mean'),brent=('brent_crude_usd','mean')).reset_index()

def slope(x,y):
    x=np.asarray(x); y=np.asarray(y)
    x_mean=x.mean(); y_mean=y.mean()
    return ((x-x_mean)*(y-y_mean)).sum()/((x-x_mean)**2).sum()

for fuel in ['petrol','diesel']:
    for grp in ['High','Low']:
        sub=g[g['subsidy_bin']==grp]
        m=slope(sub['brent'], sub[fuel])
        print(f'{fuel} slope {grp}:', m)
PY"}

